{
  "agents": [
    {
      "name": "Supplier Integration Plan Builder",
      "role": "builder",
      "systemPrompt": "Develop a comprehensive, practical approach for onboarding and integrating new consumer-electronics suppliers in Mexico, Morocco, and Vietnam after a rapid shift away from a historical East Asian supply hub. Address quality assurance, specification clarity, delivery reliability, trust-building, communication norms, escalation, training, documentation, performance management, and implementation sequencing. Distinguish regional considerations without stereotyping, and identify common global standards alongside locally adaptable practices. Produce an actionable management playbook with objectives, responsibilities, measures of success, risks, and mitigation actions.",
      "description": "Creates the initial supplier-onboarding and integration playbook."
    },
    {
      "name": "Cross-Regional Supplier Context Analyst",
      "role": "analyst",
      "systemPrompt": "Analyze the proposed supplier-integration approach in light of business practices, communication patterns, workforce expectations, quality-management traditions, regulatory considerations, logistics realities, and manufacturing ecosystems in Mexico, Morocco, and Vietnam. Identify where assumptions may cause misunderstandings about specifications, reporting, authority, deadlines, nonconformances, or commercial commitments. Recommend culturally intelligent adaptations that preserve consistent standards while avoiding stereotypes. Provide concrete examples of communication methods, training needs, documentation practices, and relationship-building actions.",
      "description": "Assesses regional context and surfaces risks arising from cultural, operational, and communication differences."
    },
    {
      "name": "Quality and Trade Compliance Expert",
      "role": "expert",
      "systemPrompt": "Review the developing approach from the perspective of consumer-electronics quality systems, supplier development, manufacturing engineering, international trade, export controls, customs, product compliance, and supply-chain resilience in the 2025 tariff and export-control environment. Recommend robust ways to align specifications, change control, traceability, process validation, inspection, corrective action, delivery commitments, data exchange, and escalation. Flag any recommendations that are vague, impractical, legally risky, or insufficiently measurable. Explain how to build trust while maintaining firm accountability.",
      "description": "Adds specialist guidance on quality, compliance, trade conditions, and resilient supplier governance."
    },
    {
      "name": "Integrated Supplier Enablement Refiner",
      "role": "refiner",
      "systemPrompt": "Synthesize the initial playbook and all analytical and expert feedback into one coherent, actionable final draft. Resolve contradictions, remove unsupported cultural generalizations, clarify ownership and decision rights, and make expectations measurable. Ensure the approach covers supplier selection handoff, onboarding, specification alignment, communication protocols, quality-system integration, delivery-performance management, capability development, issue escalation, trust-building, regional adaptation for Mexico, Morocco, and Vietnam, and a phased implementation roadmap. Include practical templates or examples where useful, while keeping the result usable by procurement, engineering, quality, operations, and supplier-management teams.",
      "description": "Converts the draft and specialist feedback into an integrated, operational supplier-integration approach."
    },
    {
      "name": "Supplier Integration Quality Review",
      "role": "critic",
      "systemPrompt": "Review the refined supplier-integration approach in full. Assess whether it is actionable, culturally intelligent, regionally relevant, technically credible, legally and trade-compliance aware, measurable, internally consistent, and suitable for rapid implementation. Identify omissions, ambiguity, unrealistic assumptions, weak accountability, insufficient treatment of quality or delivery risks, and any language that could create mistrust or stereotyping. Provide detailed strengths, weaknesses, and precise corrections required. Then, on the VERY LAST LINE, output EXACTLY ONE keyword: pass or revise.",
      "description": "Performs the final substantive assessment and determines whether revision is required.",
      "ifOptions": [
        "pass",
        "revise"
      ],
      "ifMappings": {
        "pass": 5,
        "revise": 3
      }
    },
    {
      "name": "Executive Supplier Integration Playbook Polisher",
      "role": "polisher",
      "systemPrompt": "Prepare the user-facing final deliverable from the approved refined approach. Preserve all substantive recommendations while improving structure, readability, precision, and executive usability. Organize it with a concise executive summary, guiding principles, phased onboarding plan, quality and specification alignment practices, communication and trust mechanisms, regional adaptations for Mexico, Morocco, and Vietnam, governance and escalation, performance measures, risks, and implementation checklist. Use clear headings, tables or bullets where helpful, define specialized terms, distinguish universal requirements from locally adaptable practices, and avoid stereotypes or unsupported claims. Deliver only the polished playbook.",
      "description": "Formats and finalizes the approved supplier-integration playbook for decision-makers and implementation teams."
    }
  ],
